INSERT INTO thermodynamics (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score, subject) VALUES
('What does the zeroth law of thermodynamics establish?', 'Conservation of energy', 'The existence of temperature and thermal equilibrium', 'Entropy always increases', 'Absolute zero is unreachable', 'The existence of temperature and thermal equilibrium', 'The zeroth law states that two systems each in thermal equilibrium with a third are in equilibrium with each other, defining temperature.', 720, 'Thermodynamics'),
('Which temperature scale has its zero point at absolute zero?', 'Celsius', 'Fahrenheit', 'Kelvin', 'Rankine only', 'Kelvin', 'The Kelvin scale is an absolute scale whose zero is absolute zero, the point of minimum thermal energy.', 700, 'Thermodynamics'),
('What is the value of absolute zero on the Celsius scale?', '0 C', '-273.15 C', '-100 C', '273.15 C', '-273.15 C', 'Absolute zero corresponds to -273.15 C, which is 0 K.', 760, 'Thermodynamics'),
('The ideal gas law is written as:', 'PV = nRT', 'PV = mRT', 'P/V = nRT', 'PVT = nR', 'PV = nRT', 'The ideal gas law relates pressure, volume, moles, and temperature through the gas constant R.', 740, 'Thermodynamics'),
('In the ideal gas law, what does R represent?', 'The Rydberg constant', 'The universal gas constant', 'The molar mass', 'The Boltzmann constant', 'The universal gas constant', 'R is the universal gas constant, approximately 8.314 J/(mol K).', 770, 'Thermodynamics'),
('According to kinetic theory, the temperature of an ideal gas is proportional to:', 'The average pressure', 'The average kinetic energy of its molecules', 'The total volume', 'The number of molecules', 'The average kinetic energy of its molecules', 'Absolute temperature is directly proportional to the average translational kinetic energy of the gas molecules.', 900, 'Thermodynamics'),
('Boyle''s law states that at constant temperature:', 'P is proportional to V', 'P is proportional to 1/V', 'V is proportional to T', 'P is proportional to T', 'P is proportional to 1/V', 'Boyle''s law states that pressure and volume are inversely proportional at constant temperature.', 820, 'Thermodynamics'),
('Charles''s law relates which two quantities at constant pressure?', 'Pressure and volume', 'Volume and temperature', 'Pressure and temperature', 'Moles and volume', 'Volume and temperature', 'Charles''s law states that volume is directly proportional to absolute temperature at constant pressure.', 840, 'Thermodynamics'),
('The first law of thermodynamics is a statement of:', 'Entropy increase', 'Conservation of energy', 'Conservation of momentum', 'Maximum efficiency', 'Conservation of energy', 'The first law expresses conservation of energy: energy is neither created nor destroyed, only transferred.', 730, 'Thermodynamics'),
('The first law is often written as dU = Q - W. What is U?', 'Work done', 'Heat added', 'Internal energy', 'Enthalpy', 'Internal energy', 'U is the internal energy of the system, a state function whose change equals heat added minus work done by the system.', 800, 'Thermodynamics'),
('For a system that does 200 J of work while absorbing 500 J of heat, the change in internal energy is:', '700 J', '300 J', '-300 J', '0 J', '300 J', 'Using dU = Q - W = 500 - 200 = 300 J.', 980, 'Thermodynamics'),
('Enthalpy H is defined as:', 'U + PV', 'U - PV', 'U + TS', 'U - TS', 'U + PV', 'Enthalpy is defined as H = U + PV and is convenient for processes at constant pressure.', 950, 'Thermodynamics'),
('At constant pressure, the heat added to a system equals the change in:', 'Internal energy', 'Enthalpy', 'Entropy', 'Gibbs free energy', 'Enthalpy', 'At constant pressure, Q equals the change in enthalpy because the PV work is accounted for in H.', 1020, 'Thermodynamics'),
('The specific heat capacity of a substance is the energy required to:', 'Melt one mole', 'Raise the temperature of one unit mass by one degree', 'Boil one kilogram', 'Change phase at constant temperature', 'Raise the temperature of one unit mass by one degree', 'Specific heat capacity is the heat needed to raise the temperature of a unit mass by one degree.', 780, 'Thermodynamics'),
('How much heat is needed to raise 2 kg of water by 10 C (c = 4186 J/kg K)?', '8372 J', '41860 J', '83720 J', '20930 J', '83720 J', 'Q = mcdeltaT = 2 x 4186 x 10 = 83720 J.', 1080, 'Thermodynamics'),
('For an ideal gas, the relationship between molar heat capacities is:', 'Cp - Cv = R', 'Cp + Cv = R', 'Cp = Cv', 'Cv - Cp = R', 'Cp - Cv = R', 'Mayer''s relation states that for an ideal gas Cp - Cv = R.', 1150, 'Thermodynamics'),
('The ratio gamma = Cp/Cv for a monatomic ideal gas is:', '5/3', '7/5', '4/3', '1', '5/3', 'For a monatomic ideal gas Cv = 3R/2 and Cp = 5R/2, so gamma = 5/3.', 1280, 'Thermodynamics'),
('An isothermal process is one that occurs at constant:', 'Pressure', 'Volume', 'Temperature', 'Entropy', 'Temperature', 'An isothermal process takes place at constant temperature.', 760, 'Thermodynamics'),
('An adiabatic process is one in which:', 'Temperature is constant', 'No heat is exchanged with surroundings', 'Pressure is constant', 'Volume is constant', 'No heat is exchanged with surroundings', 'In an adiabatic process Q = 0, so no heat flows in or out of the system.', 820, 'Thermodynamics'),
('An isobaric process occurs at constant:', 'Temperature', 'Volume', 'Pressure', 'Internal energy', 'Pressure', 'An isobaric process is carried out at constant pressure.', 740, 'Thermodynamics'),
('An isochoric (isovolumetric) process occurs at constant:', 'Pressure', 'Volume', 'Temperature', 'Enthalpy', 'Volume', 'An isochoric process occurs at constant volume, so the gas does no work.', 760, 'Thermodynamics'),
('In an isochoric process, the work done by the gas is:', 'Equal to the heat added', 'Zero', 'Equal to PV', 'Negative', 'Zero', 'Since volume does not change, W = PdV = 0 for an isochoric process.', 900, 'Thermodynamics'),
('On a PV diagram, the work done by a gas equals:', 'The slope of the curve', 'The area under the curve', 'The y-intercept', 'The length of the curve', 'The area under the curve', 'Work done by a gas is the integral of P dV, represented by the area under the process curve on a PV diagram.', 990, 'Thermodynamics'),
('For an isothermal expansion of an ideal gas, the work done by the gas is:', 'nRT ln(V2/V1)', 'nR(T2 - T1)', 'PdeltaV', 'Zero', 'nRT ln(V2/V1)', 'For isothermal expansion W = nRT ln(V2/V1), derived by integrating P = nRT/V.', 1450, 'Thermodynamics'),
('In an adiabatic process for an ideal gas, which relation holds?', 'PV = constant', 'PV^gamma = constant', 'P/V = constant', 'V/T = constant', 'PV^gamma = constant', 'For a reversible adiabatic process, PV^gamma is constant where gamma is the heat capacity ratio.', 1380, 'Thermodynamics'),
('Two moles of an ideal gas expand isothermally at 300 K from 1 L to 2 L. The work done (R = 8.314) is approximately:', '1729 J', '3458 J', '865 J', '5000 J', '3458 J', 'W = nRT ln(V2/V1) = 2 x 8.314 x 300 x ln(2) = 3458 J.', 1620, 'Thermodynamics'),
('The second law of thermodynamics, in the Clausius statement, says heat cannot spontaneously flow from:', 'Hot to cold', 'Cold to hot', 'High to low pressure', 'Gas to liquid', 'Cold to hot', 'The Clausius statement says heat cannot flow spontaneously from a colder body to a hotter body.', 900, 'Thermodynamics'),
('Entropy is a measure of:', 'Total energy', 'Disorder or number of microstates', 'Temperature', 'Pressure', 'Disorder or number of microstates', 'Entropy quantifies the disorder of a system, related to the number of accessible microstates.', 850, 'Thermodynamics'),
('For a reversible process, the change in entropy is defined as:', 'dS = Q/T', 'dS = integral of dQ_rev/T', 'dS = W/T', 'dS = U/T', 'dS = integral of dQ_rev/T', 'Entropy change for a reversible process is the integral of dQ_rev divided by absolute temperature.', 1200, 'Thermodynamics'),
('In any spontaneous process in an isolated system, the total entropy:', 'Decreases', 'Stays constant', 'Increases', 'Becomes zero', 'Increases', 'The second law requires that the total entropy of an isolated system increases for spontaneous (irreversible) processes.', 880, 'Thermodynamics'),
('What is the entropy change when 1 kg of ice melts at 0 C? (latent heat = 334000 J/kg)', '1223 J/K', '334000 J/K', '273 J/K', '0 J/K', '1223 J/K', 'deltaS = Q/T = 334000 / 273.15 = 1223 J/K, since melting occurs at constant temperature.', 1700, 'Thermodynamics'),
('A heat engine takes in heat Qh and rejects Qc. Its efficiency is:', '1 - Qc/Qh', 'Qc/Qh', '1 - Qh/Qc', 'Qh/Qc', '1 - Qc/Qh', 'Thermal efficiency is the net work divided by heat input, equal to 1 - Qc/Qh.', 1100, 'Thermodynamics'),
('The efficiency of a Carnot engine operating between temperatures Th and Tc is:', '1 - Tc/Th', 'Tc/Th', '1 - Th/Tc', 'Th/Tc', '1 - Tc/Th', 'The Carnot efficiency depends only on the absolute temperatures: eta = 1 - Tc/Th.', 1250, 'Thermodynamics'),
('A Carnot engine operates between 600 K and 300 K. Its maximum efficiency is:', '25%', '50%', '75%', '100%', '50%', 'eta = 1 - Tc/Th = 1 - 300/600 = 0.50, or 50%.', 1300, 'Thermodynamics'),
('Why is no real heat engine 100% efficient?', 'Energy is destroyed', 'Some heat must be rejected to a cold reservoir', 'Work is created from nothing', 'Friction adds energy', 'Some heat must be rejected to a cold reservoir', 'The second law requires that some heat be rejected to a cold reservoir, so efficiency is always below 100%.', 980, 'Thermodynamics'),
('The coefficient of performance (COP) of a refrigerator is defined as:', 'Qc/W', 'W/Qc', 'Qh/W', 'W/Qh', 'Qc/W', 'A refrigerator''s COP is the heat removed from the cold space divided by the work input, Qc/W.', 1180, 'Thermodynamics'),
('A refrigerator removes 600 J from its interior using 150 J of work. Its COP is:', '4', '0.25', '5', '3', '4', 'COP = Qc/W = 600/150 = 4.', 1350, 'Thermodynamics'),
('A Carnot refrigerator operates between 250 K and 300 K. Its maximum COP is:', '5', '6', '4', '0.2', '5', 'COP_carnot = Tc/(Th - Tc) = 250/(300-250) = 5.', 1750, 'Thermodynamics'),
('The third law of thermodynamics states that as temperature approaches absolute zero:', 'Pressure approaches zero', 'Entropy approaches a constant minimum (zero for a perfect crystal)', 'Volume approaches infinity', 'Internal energy approaches infinity', 'Entropy approaches a constant minimum (zero for a perfect crystal)', 'The third law states that the entropy of a perfect crystal approaches zero as temperature approaches absolute zero.', 1050, 'Thermodynamics'),
('During a phase transition at constant pressure, the temperature of the substance:', 'Rises steadily', 'Falls steadily', 'Remains constant', 'Oscillates', 'Remains constant', 'During a phase change the temperature stays constant while latent heat is absorbed or released.', 820, 'Thermodynamics'),
('Latent heat of vaporization is the energy required to:', 'Raise temperature by one degree', 'Convert a unit mass from liquid to gas at constant temperature', 'Melt a unit mass of solid', 'Ionize a gas', 'Convert a unit mass from liquid to gas at constant temperature', 'Latent heat of vaporization is the heat needed to convert a unit mass of liquid to vapor at constant temperature.', 880, 'Thermodynamics'),
('How much heat is needed to boil 0.5 kg of water already at 100 C? (Lv = 2260000 J/kg)', '1130000 J', '2260000 J', '565000 J', '4520000 J', '1130000 J', 'Q = mLv = 0.5 x 2260000 = 1130000 J.', 1250, 'Thermodynamics'),
('Heat transfer through direct contact within a solid, without bulk motion, is called:', 'Convection', 'Radiation', 'Conduction', 'Advection', 'Conduction', 'Conduction transfers heat through a material by molecular collisions without bulk movement of matter.', 720, 'Thermodynamics'),
('Heat transfer by the bulk movement of a fluid is called:', 'Conduction', 'Convection', 'Radiation', 'Diffusion', 'Convection', 'Convection transfers heat through the bulk motion of fluids carrying thermal energy.', 740, 'Thermodynamics'),
('Heat transfer that requires no medium and travels via electromagnetic waves is:', 'Conduction', 'Convection', 'Radiation', 'Conduction and convection', 'Radiation', 'Radiation transfers energy through electromagnetic waves and requires no material medium.', 760, 'Thermodynamics'),
('The Stefan-Boltzmann law states that radiated power is proportional to:', 'T', 'T squared', 'T to the fourth power', 'T cubed', 'T to the fourth power', 'The Stefan-Boltzmann law states that radiated power per unit area is proportional to the fourth power of absolute temperature.', 1300, 'Thermodynamics'),
('The rate of conductive heat flow through a slab is proportional to:', 'The thickness of the slab', 'The temperature difference across it', 'The fourth power of temperature', 'The inverse of area', 'The temperature difference across it', 'Fourier''s law gives conductive heat flow proportional to area and temperature gradient, hence the temperature difference.', 1150, 'Thermodynamics'),
('The Gibbs free energy is defined as:', 'G = H - TS', 'G = U - TS', 'G = H + TS', 'G = U + PV', 'G = H - TS', 'Gibbs free energy is G = H - TS and determines spontaneity at constant temperature and pressure.', 1200, 'Thermodynamics'),
('A process at constant temperature and pressure is spontaneous when:', 'deltaG > 0', 'deltaG = 0', 'deltaG < 0', 'deltaH < 0 only', 'deltaG < 0', 'A negative change in Gibbs free energy indicates a spontaneous process at constant T and P.', 1280, 'Thermodynamics'),
('The Helmholtz free energy A = U - TS determines spontaneity at constant temperature and constant:', 'Pressure', 'Volume', 'Enthalpy', 'Entropy', 'Volume', 'Helmholtz free energy A = U - TS governs spontaneity for processes at constant temperature and volume.', 1900, 'Thermodynamics');
